/* 十四張貼圖，內嵌成 data: URI。
   容器規範 §3 明確允許 <img> / CSS 背景圖用 data:（base64 內嵌）。

   為什麼不用 .webp 檔案：Chrome 把每個本地檔案當成獨立來源，所以在
   file:// 下用 new Image() 讀 ./assets/tex/x.webp 會污染 canvas ——
   getImageData 抛 SecurityError，更要命的是 WebGL 的 texSubImage2D
   連上傳都拒絕，貼圖整個用不了。data: URI 同源，沒有這個問題，代價是
   base64 比二進位大三分之一。雙擊 index.html 就能看，值這個錢。 */
window.TEX={"ashlar": "data:image/webp;base64,", "goldleaf": "data:image/webp;base64,", "greenglaze": "data:image/webp;base64,", "ishigaki": "data:image/webp;base64,", "iznik": "data:image/webp;base64,", "kawara": "data:image/webp;base64,", "laterite": "data:image/webp;base64,", "leadroof": "data:image/webp;base64,", "orangetile": "data:image/webp;base64,", "pine": "data:image/webp;base64,", "redwall": "data:image/webp;base64,", "sandstone": "data:image/webp;base64,", "shikkui": "data:image/webp;base64,", "timber": "data:image/webp;base64,"};
